/**
 * Real Halloween scare image: Graeme Maclean, Wikimedia Commons.
 * License: CC BY 2.0.
 * Canonical source: Wikimedia Commons — "Scary clown.jpg" by Graeme Maclean.
 * License: CC BY 2.0 (commercial use allowed with attribution).
 * Source: https://commons.wikimedia.org/wiki/File:Scary_clown.jpg
 * The bundled copy is a local resized/cropped derivative used only as a game asset.
 */
export const HALLOWEEN_SCARE_IMAGE = "data:image/jpeg;base64,";


let preloadedImage: HTMLImageElement | null = null;

/**
 * Decode the bundled image before a scare is needed so the first frame never
 * waits for a network request or image decode.
 */
export async function preloadHalloweenScareImage(): Promise<void> {
  if (typeof window === "undefined") return;
  if (preloadedImage?.complete) return;
  try {
    const image = preloadedImage ?? new Image();
    preloadedImage = image;
    image.decoding = "async";
    image.src = HALLOWEEN_SCARE_IMAGE;
    if (image.decode) {
      await image.decode();
    } else {
      await new Promise<void>((resolve) => {
        image.onload = () => resolve();
        image.onerror = () => resolve();
      });
    }
  } catch {
    // The bundled image remains the fallback; never block gameplay.
  }
}

export const HALLOWEEN_SCARE_ASSET_CREDIT =
  "Scary clown.jpg — Graeme Maclean, Wikimedia Commons, CC BY 2.0. " +
  "https://commons.wikimedia.org/wiki/File:Scary_clown.jpg";
